1	/**
2	 * 扩展行动库
3	 *
4	 * 涵盖：街头生存 / 经营 / 社交 / 学习 / 生活 / 投资 / 梦想实现
5	 * 参考：《北京浮生记》《大多数》《中国式家长》《这是我的战争》《Stardew Valley》
6	 *
7	 * 用法：getAvailableActions() 末尾会调用 addExtraActions() 把这些行动合并进去
8	 */
9	
10	/** 街头阶段通用行动（不依赖地点） */
11	function addStreetExtras(state, actions) {
12	  // === 街头生存类（任何街头地点都行） ===
13	  actions.push({
14	    id: "scavenge_trash",
15	    name: "规划拾荒路线",
16	    desc: "选择今天的拾荒区域：城中村小巷(稳)/废品站边缘(中)/工业区(高)/老周专线(⭐)。不同路线收益和风险各异。",
17	    icon: "🗺️",
18	    apCost: 15,
19	    payEstimate: "2~65",
20	    handler: () => {
21	      showScavengeRouteModal();
22	    },
23	  });
24	
25	  actions.push({
26	    id: "vending_advice",
27	    name: "摆摊选址建议",
28	    desc: "根据天气、节日、周末等因素，智能推荐今日最佳摆摊地点。",
29	    icon: "📍",
30	    apCost: 5,
31	    handler: () => {
32	      if (typeof showVendingLocationAdviceModal === "function") {
33	        showVendingLocationAdviceModal();
34	      } else {
35	        StateManager.addMessage("功能暂未加载", "warning");
36	      }
37	    },
38	  });
39	
40	  actions.push({
41	    id: "busking",
42	    name: "街头卖唱",
43	    desc: "在地铁口或天桥上唱歌赚打赏。需要胆子大。",
44	    icon: "🎤",
45	    apCost: 20,
46	    payEstimate: "5~25",
47	    handler: () => {
48	      const st = StateManager.getState();
49	      const skill = st.player.mental; // 心智影响成功率
50	      const earned = Math.floor(5 + Math.random() * 20 + (skill - 25) * 0.3);
51	      st.resources.cash += earned;
52	      st.resources.totalEarned += earned;
53	      addDailyTransaction(st, "income", "side_job", earned, "街头卖唱");
54	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 10);
55	      st.player.fame = Math.min(100, st.player.fame + 1);
56	      if (Math.random() < 0.2) {
57	        st.needs.happiness = Math.max(0, st.needs.happiness - 5);
58	        StateManager.addMessage(
59	          `🎤 唱了半天，城管赶人+路人嫌弃，赚到 ¥${earned}。`,
60	          "warning",
61	        );
62	      } else {
63	        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
64	        StateManager.addMessage(
65	          `🎤 卖唱结束，收获 ¥${earned} 打赏！心情好。`,
66	          "success",
67	        );
68	      }
69	      consumeAP(20);
70	    },
71	  });
72	
73	  actions.push({
74	    id: "beg",
75	    name: "街头乞讨",
76	    desc: "放下尊严，跪地要饭。（有尊严损失）",
77	    icon: "🙏",
78	    apCost: 20,
79	    payEstimate: "1~5",
80	    handler: () => {
81	      const st = StateManager.getState();
82	      const earned = 1 + Math.floor(Math.random() * 5);
83	      st.resources.cash += earned;
84	      st.resources.totalEarned += earned;
85	      addDailyTransaction(st, "income", "side_job", earned, "街头乞讨");
86	      st.needs.happiness = Math.max(0, st.needs.happiness - 12);
87	      st.player.fame = Math.max(0, st.player.fame - 2);
88	      st.flags._everBegged = true; // 成就追踪
89	      StateManager.addMessage(
90	        `🙏 跪了半小时，收到 ¥${earned}。心里五味杂陈。`,
91	        "warning",
92	      );
93	      consumeAP(20);
94	    },
95	  });
96	
97	  actions.push({
98	    id: "play_dice",
99	    name: "路边赌骰子",
100	    desc: "和地摊小贩玩骰子，押 50 赢了翻倍，输了打水漂。",
101	    icon: "🎲",
102	    costEstimate: 50,
103	    apCost: 20,
104	    payEstimate: "0或100",
105	    handler: () => {
106	      const st = StateManager.getState();
107	      if (st.resources.cash < 50) {
108	        StateManager.addMessage("🎲 押不起 50 块。", "warning");
109	        return;
110	      }
111	      st.resources.cash -= 50;
112	      addDailyTransaction(st, "expense", "entertainment", 50, "赌博押注");
113	      if (Math.random() < 0.45) {
114	        st.resources.cash += 100;
115	        st.resources.totalEarned += 50;
116	        addDailyTransaction(st, "income", "side_job", 100, "赌博赢钱");
117	        st.needs.happiness = Math.min(100, st.needs.happiness + 10);
118	        st.flags._everWonGamble = true; // 成就追踪
119	        StateManager.addMessage("🎲 赢了！100 块到手！", "success");
120	      } else {
121	        st.needs.happiness = Math.max(0, st.needs.happiness - 8);
122	        StateManager.addMessage("🎲 输了...50 块没了。", "danger");
123	      }
124	      consumeAP(20);
125	    },
126	  });
127	
128	  // === 社交 / 家庭类 ===
129	  actions.push({
130	    id: "call_home",
131	    name: "给家里打电话",
132	    desc: "用公用电话给爸妈报平安，听听唠叨。",
133	    icon: "📞",
134	    costEstimate: 2,
135	    handler: () => {
136	      const st = StateManager.getState();
137	      if (st.resources.cash < 2) {
138	        StateManager.addMessage("📞 电话费都付不起...", "warning");
139	        return;
140	      }
141	      st.resources.cash -= 2;
142	      addDailyTransaction(st, "expense", "misc", 2, "给家里打电话");
143	      st.needs.happiness = Math.min(100, st.needs.happiness + 15);
144	      st.needs.hunger = Math.max(0, st.needs.hunger - 3);
145	      if (Math.random() < 0.3) {
146	        st.resources.cash += 200; // 爸妈塞的钱
147	        addDailyTransaction(st, "income", "gift", 200, "爸妈给的零花钱");
148	        StateManager.addMessage(
149	          "📞 妈妈在电话里哭了，让你注意身体，转了 200 块。",
150	          "success",
151	        );
152	        st.resources.totalEarned += 200;
153	      } else {
154	        StateManager.addMessage(
155	          "📞 和爸妈聊了 10 分钟，心情好多了。",
156	          "success",
157	        );
158	      }
159	      consumeAP(20);
160	    },
161	  });
162	
163	  actions.push({
164	    id: "remit_home",
165	    name: "给家里汇款",
166	    desc: "把一部分钱寄回老家。",
167	    icon: "💌",
168	    costEstimate: "200~1000",
169	    handler: () => {
170	      showRemitModal();
171	    },
172	  });
173	
174	  actions.push({
175	    id: "internet_bar",
176	    name: "网吧上网",
177	    desc: "花 5 块在网吧上 2 小时网，可以查资料、刷视频、玩游戏。",
178	    icon: "💻",
179	    costEstimate: 5,
180	    apCost: 20,
181	    payEstimate: "智力+0.3, 随机技能XP",
182	    disabled: state.resources.cash < 5,
183	    reqFail: state.resources.cash < 5 ? "现金不足" : null,
184	    handler: () => {
185	      const st = StateManager.getState();
186	      if (st.resources.cash < 5) {
187	        StateManager.addMessage("💻 5 块都掏不出来。", "warning");
188	        return;
189	      }
190	      st.resources.cash -= 5;
191	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 8);
192	      st.player.intelligence = Math.min(100, st.player.intelligence + 0.3);
193	      const skills = ["english", "coding", "accounting"];
194	      const sk = skills[Math.floor(Math.random() * skills.length)];
195	      st.skills[sk].xp += 5 + Math.floor(Math.random() * 10);
196	      st.needs.happiness = Math.min(100, st.needs.happiness + 5);
197	      StateManager.addMessage(
198	        "💻 在网吧待了 2 小时，智力+，还有点收获。",
199	        "info",
200	      );
201	      consumeAP(20);
202	    },
203	  });
204	
205	  actions.push({
206	    id: "salon_chat",
207	    name: "路边理发店聊天",
208	    desc: "花 10 块剪个头发，顺便听听老板吹牛。需要敏捷≥18才能帮上忙。",
209	    icon: "💈",
210	    costEstimate: 10,
211	    apCost: 20,
212	    payEstimate: "心情+10",
213	    disabled: state.player.agility < 18 || state.resources.cash < 10,
214	    reqFail:
215	      state.player.agility < 18
216	        ? "需敏捷≥18"
217	        : state.resources.cash < 10
218	          ? "现金不足"
219	          : null,
220	    handler: () => {
221	      const st = StateManager.getState();
222	      if (st.resources.cash < 10) {
223	        StateManager.addMessage("💈 剪不起头。", "warning");
224	        return;
225	      }
226	      st.resources.cash -= 10;
227	      st.needs.hygiene = Math.min(100, st.needs.hygiene + 25);
228	      st.needs.happiness = Math.min(100, st.needs.happiness + 10);
229	      st.player.fame = Math.min(100, st.player.fame + 1);
230	      StateManager.addMessage(
231	        "💈 剪了个利索的短发！清爽多了，运气好像也好了点。",
232	        "success",
233	      );
234	      consumeAP(20);
235	    },
236	  });
237	
238	  // === 学习类 ===
239	  actions.push({
240	    id: "self_study",
241	    name: "图书馆自习",
242	    desc: "去图书馆（商业区旁）安静看书。",
243	    icon: "📖",
244	    apCost: 20,
245	    payEstimate: "技能XP+30",
246	    handler: () => {
247	      const st = StateManager.getState();
248	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 10);
249	      const skills = Object.keys(st.skills);
250	      const key = skills[Math.floor(Math.random() * skills.length)];
251	      // 小美好感60解锁图书馆内部账号：学习效率+30%
252	      var xpMult = st.flags.xiaomeiLibrary ? 1.3 : 1.0;
253	      var xpGain = Math.floor((30 + Math.floor(Math.random() * 20)) * xpMult);
254	      st.skills[key].xp += xpGain;
255	      st.player.intelligence = Math.min(100, st.player.intelligence + 0.2);
256	      var libTag = st.flags.xiaomeiLibrary
257	        ? "（小美的图书馆账号让效率提升30%）"
258	        : "";
259	      StateManager.addMessage(
260	        `📖 在图书馆泡了一下午，${key} XP+${xpGain}${libTag}！`,
261	        "success",
262	      );
263	      consumeAP(20);
264	    },
265	  });
266	
267	  actions.push({
268	    id: "night_school",
269	    name: "上夜校",
270	    desc: "晚上上夜校，提升智力+相关技能。需要 ¥50 学费，智力≥25。",
271	    icon: "🌃",
272	    costEstimate: 50,
273	    apCost: 20,
274	    payEstimate: "智力+1, 技能+",
275	    disabled: state.player.intelligence < 25 || state.resources.cash < 50,
276	    reqFail:
277	      state.player.intelligence < 25
278	        ? "需智力≥25"
279	        : state.resources.cash < 50
280	          ? "现金不足"
281	          : null,
