296	        "success",
297	      );
298	      consumeAP(20);
299	    },
300	  });
301	
302	  // === 生活类 ===
303	  actions.push({
304	    id: "gym",
305	    name: "办健身卡锻炼",
306	    desc: "去健身房办月卡，提升体质和敏捷。",
