1542	        '<button class="btn btn-sm" onclick="ingredientBuyQty(\'' +
1543	        g.id +
1544	        '\', 1)" style="width:24px;height:24px;padding:0;">+</button>';
1545	      html +=
1546	        '<button class="btn btn-primary btn-sm" onclick="ingredientBuyConfirm(\'' +
1547	        g.id +
1548	        "'," +
1549	        price +
1550	        ')" style="padding:4px 10px;">买</button>';
1551	      html += "</div></div>";
1552	    }
1553	  }
1554	
1555	  html += "</div>"; // scrollable
1556	  html += '<div style="text-align:center;margin-top:12px;">';
1557	  html +=
1558	    '<button class="btn btn-secondary" onclick="this.closest(\'.modal-overlay\').remove()">关闭</button>';
1559	  html += "</div></div>";
1560	
1561	  if (typeof showModal === "function") {
1562	    showModal({
1563	      title: "🛒 购买食材",
1564	      body: html,
1565	      buttons: [],
1566	    });
1567	  } else {
1568	    var overlay = document.createElement("div");
1569	    overlay.className = "modal-overlay";
1570	    overlay.innerHTML =
1571	      '<div class="modal-box" style="max-width:520px;">' + html + "</div>";
1572	    document.body.appendChild(overlay);
1573	  }
1574	}
1575	
1576	/** 食材数量调节 */
1577	function ingredientBuyQty(goodId, delta) {
1578	  var span = document.getElementById("ing_qty_" + goodId);
1579	  if (!span) return;
1580	  var cur = parseInt(span.textContent) || 0;
1581	  cur = Math.max(0, cur + delta);
1582	  span.textContent = cur;
1583	}
1584	
1585	/** 食材购买确认 */
1586	function ingredientBuyConfirm(goodId, unitPrice) {
1587	  var span = document.getElementById("ing_qty_" + goodId);
1588	  if (!span) return;
1589	  var qty = parseInt(span.textContent) || 0;
1590	  if (qty <= 0) {
1591	    StateManager.addMessage("⚠️ 请先选择数量。", "warning");
1592	    return;
1593	  }
1594	
1595	  var state = StateManager.getState();
1596	  var totalCost = qty * unitPrice;
1597	
1598	  if ((state.resources.cash || 0) < totalCost) {
1599	    StateManager.addMessage(
1600	      "💸 现金不足！需要 ¥" + totalCost.toFixed(2),
1601	      "warning",
1602	    );
1603	    return;
1604	  }
1605	
1606	  // 检查背包容量
1607	  var capacity = state.inventory ? state.inventory.capacity || 20 : 20;
1608	  var usedSlots =
1609	    state.inventory && state.inventory.items
1610	      ? state.inventory.items.reduce(function (s, it) {
1611	          return s + (it.qty || 0);
1612	        }, 0)
1613	      : 0;
1614	  if (usedSlots + qty > capacity) {
1615	    StateManager.addMessage(
1616	      "🎒 背包空间不足！可用 " + (capacity - usedSlots) + " 格。",
1617	      "warning",
1618	    );
1619	    return;
1620	  }
1621	
1622	  // 扣钱
1623	  state.resources.cash -= totalCost;
1624	
1625	  // 加库存（带购买日用于保鲜）
1626	  state.inventory = state.inventory || { items: [], capacity: 20 };
1627	  var existing = null;
1628	  for (var i = 0; i < state.inventory.items.length; i++) {
1629	    if (state.inventory.items[i].id === goodId) {
1630	      existing = state.inventory.items[i];
1631	      break;
1632	    }
1633	  }
1634	  if (existing) {
1635	    existing.qty += qty;
1636	  } else {
1637	    state.inventory.items.push({
1638	      id: goodId,
1639	      qty: qty,
1640	      boughtDay: state.player.day || 0,
1641	      perishDays: (function () {
1642	        var def =
1643	          typeof getItemById === "function" ? getItemById(goodId) : null;
1644	        return def ? def.perishDays : 7;
1645	      })(),
1646	    });
1647	  }
1648	
1649	  // 添加购买记录
1650	  if (typeof addDailyTransaction === "function") {
1651	    addDailyTransaction(state, "expense", "ingredient", totalCost, goodId);
1652	  }
1653	
1654	  StateManager.addMessage(
1655	    "🛒 购买了 " + qty + " 份食材。花费 ¥" + totalCost.toFixed(2),
1656	    "success",
1657	  );
1658	
1659	  // 刷新弹窗
1660	  var overlay = document.querySelector(".modal-overlay");
1661	  if (overlay) overlay.remove();
1662	
1663	  // 重新打开购物窗口
1664	  showIngredientShopModal();
1665	  if (typeof renderAll === "function") renderAll();
1666	}
1667	
1668	/** 医院解锁的"看病"行动 */
1669	function addClinicAction(state, actions) {
1670	  if (state.trade.currentLocation !== "hospital") return;
1671	  var illCount = (state.status.illnesses && state.status.illnesses.length) || 0;
1672	  actions.push({
1673	    id: "see_doctor",
1674	    name: "看病" + (illCount ? "（你有 " + illCount + " 种疾病）" : ""),
1675	    desc: "由医生检查并选择治疗方案：药店/医院两档可选。",
1676	    icon: "🏥",
1677	    apCost: 5,
1678	    handler: function () {
1679	      if (typeof openClinicModal === "function") openClinicModal();
1680	      consumeAP(5);
1681	    },
1682	  });
1683	}
1684	
1685	/** 给 main.js 调用的统一入口 */
1686	function addExtraActions(state, actions) {
1687	  if (state.player.phase === "street") {
1688	    addStreetExtras(state, actions);
1689	    addAmenityActions(state, actions);
1690	    addHomeActions(state, actions);
1691	    addClinicAction(state, actions);
1692	    addIngredientShoppingActions(state, actions);
1693	  }
1694	  // 余额宝每日利息
1695	  if (state.flags.yuEBao > 0) {
1696	    const interest = Math.floor(state.flags.yuEBao * 0.0001);
1697	    if (interest > 0) {
1698	      state.flags.yuEBao += interest;
1699	    }
1700	  }
1701	  // 保险检查
1702	  if (
1703	    state.flags.hasInsurance &&
1704	    state.flags.insuranceExpire < state.player.day
1705	  ) {
1706	    state.flags.hasInsurance = false;
1707	    StateManager.addMessage("🛡️ 你的保险到期了，记得续保。", "info");
1708	  }
1709	  if (state.flags.hasInsurance && (state.status.injured || state.status.sick)) {
1710	    if (!state.flags._insurancePaidThisCycle) {
1711	      state.resources.cash += 500;
1712	      state.flags._insurancePaidThisCycle = true;
1713	      StateManager.addMessage("🛡️ 保险赔付了 ¥500！", "success");
1714	    }
1715	  }
1716	  if (!state.status.injured && !state.status.sick) {
1717	    state.flags._insurancePaidThisCycle = false;
1718	  }
1719	}
1720	
1721	// ========== 家居行动（回住所做饭/洗澡/休息） ==========
1722	
1723	/**
1724	 * 添加「回住所」家居行动到 action 列表。
1725	 * 根据住所等级显示可用的做饭/洗澡/休息选项。
1726	 * 旅行AP = 从当前位置到住所位置的路径花费。
1727	 */
1728	function addHomeActions(state, actions) {
1729	  var tier = state.housing ? state.housing.tier || 0 : 0;
1730	  if (tier <= 0) return;
1731	
1732	  var homeLoc =
1733	    typeof getHomeLocationKey === "function" ? getHomeLocationKey(state) : null;
1734	  if (!homeLoc) return;
1735	
1736	  var homeAmenities =
1737	    typeof getHomeAmenities === "function" ? getHomeAmenities(state) : [];
1738	  if (homeAmenities.length === 0) return;
1739	
1740	  var curLoc = state.trade.currentLocation;
1741	  var travelAp =
1742	    typeof getTravelApCost === "function"
1743	      ? getTravelApCost(curLoc, homeLoc, state)
1744	      : curLoc === homeLoc
1745	        ? 0
1746	        : 10;
1747	  var isAtHome = curLoc === homeLoc;
1748	
1749	  var cookingAvail = homeAmenities.some(function (a) {
1750	    return a.id.indexOf("cook") >= 0;
1751	  });
1752	  var bathAvail = homeAmenities.some(function (a) {
1753	    return a.id.indexOf("bath") >= 0;
1754	  });
1755	  var restAvail = homeAmenities.some(function (a) {
1756	    return a.id.indexOf("nap") >= 0;
1757	  });
1758	  var icons = [];
1759	  if (cookingAvail) icons.push("🍳");
1760	  if (bathAvail) icons.push("🚿");
1761	  if (restAvail) icons.push("🛏️");
1762	
1763	  actions.push({
1764	    id: "go_home",
1765	    name: "🏠 回住所",
1766	    icon: "🏠",
1767	    desc:
1768	      (isAtHome ? "在家中" : "回到住所") +
1769	      " — " +
1770	      icons.join(" ") +
1771	      " | " +
1772	      (isAtHome ? "🏠 已在住所" : "⚡ 需" + travelAp + "AP回家"),
1773	    apCost: travelAp,
1774	    category: "restore",
1775	    handler: function () {
1776	      var s = StateManager.getState();
1777	      showHomeActionsModal(s);
1778	    },
1779	  });
1780	}
1781	
1782	/** 显示家居设施选择弹窗 */
1783	function showHomeActionsModal(state) {
1784	  var homeAmenities =
1785	    typeof getHomeAmenities === "function" ? getHomeAmenities(state) : [];
1786	  if (homeAmenities.length === 0) {
1787	    StateManager.addMessage("🏠 住所没有可用的设施。", "info");
1788	    return;
1789	  }
1790	  var html =
1791	    '<div style="font-size:13px;margin-bottom:10px;color:var(--text-secondary);">选择一项居家活动：</div>';
1792	  for (var i = 0; i < homeAmenities.length; i++) {
1793	    var a = homeAmenities[i];
1794	    var pd = [];
1795	    if (a.primary) {
1796	      for (var k in a.primary) {
1797	        if (!a.primary.hasOwnProperty(k)) continue;
1798	        var amt = a.primary[k];
1799	        var lb =
1800	          {
1801	            hunger: "饥饱",
1802	            fatigue: "疲劳",
1803	            hygiene: "卫生",
1804	            happiness: "心情",
1805	          }[k] || k;
1806	        pd.push(lb + (amt >= 0 ? "+" : "") + amt);
1807	      }
1808	    }
1809	    html +=
1810	      '<div class="action-card" style="margin-bottom:8px;padding:10px;cursor:pointer;border:1px solid var(--border);border-radius:8px;" data-amenity-id="' +
1811	      a.id +
1812	      '">' +
1813	      '<div style="display:flex;justify-content:space-between;align-items:center;">' +
1814	      '<span style="font-weight:600;">' +
1815	      (a.icon || "🏠") +
1816	      " " +
1817	      a.name +
1818	      "</span>" +
1819	      '<span style="font-size:11px;color:var(--text-muted);">⚡' +
1820	      (a.ap || 0) +
1821	      "AP | " +
1822	      (a.cost > 0 ? "¥" + a.cost : "免费") +
1823	      "</span></div>" +
1824	      '<div style="font-size:11px;color:var(--text-secondary);margin-top:4px;">' +
1825	      pd.join(" → ") +
1826	      "</div>" +
1827	      '<div style="font-size:10px;color:var(--text-muted);margin-top:2px;">' +
1828	      a.desc +
1829	      "</div></div>";
1830	  }
1831	  showModal({
1832	    title: "🏠 在住所",
1833	    body: html,
1834	    buttons: [{ text: "出门", cls: "", callback: function () {} }],
1835	  });
1836	  setTimeout(function () {
1837	    var ov = document.querySelector(".modal-overlay");
1838	    if (!ov) return;
1839	    for (var j = 0; j < homeAmenities.length; j++) {
1840	      (function (aid) {
1841	        var el = ov.querySelector('[data-amenity-id="' + aid + '"]');
1842	        if (el) {
1843	          el.addEventListener("click", function () {
1844	            var o = document.querySelector(".modal-overlay");
1845	            if (o && o.parentNode) o.parentNode.removeChild(o);
1846	            if (typeof travelToAmenityAndUse === "function")
1847	              travelToAmenityAndUse(aid);
1848	            else if (typeof useAmenity === "function") useAmenity(aid);
1849	          });
1850	        }
